window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b6f3161b044f63d6"]={"versions": [{"id": "FIG-b6f3161b044f63d6", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Adressierungsdiagramm zur Bitaufteilung und linearen Speicherabbildung im Kontext der AUTOSAR Flash EEPROM Emulation (FEE). Das Diagramm illustriert das Zusammenspiel zwischen einer 16-Bit-Blockkennung (NVRAM-Blocknummer und Dataset-Index) und dem physischen Adressraum der Datensätze.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei Hauptstrukturen:</p>\n<ul class=\"fig-list\"><li>Ein 16-Bit-Register/Feld, aufgeteilt in:\n<ul class=\"fig-list\"><li>12 höherwertige Bits (blau hinterlegt): Kennzeichnung für die logische <code>Block number</code>.\n</li><li>4 niederwertige Bits (türkis hinterlegt): Kennzeichnung für den <code>Dataset index</code>.\n</li></ul>\n</li><li>Eine funktionale Verarbeitungseinheit <code>Address conversion</code>, visualisiert als kreisförmiger Knoten mit Verbindungslinie zur <code>Block number</code>.\n</li><li>Ein vertikaler linearer Adressraum (Speicherabbild), schraffiert mit reservierten/umgebenden Speicherbereichen und einem aktiv adressierten Blockbereich. Dieser enthält vier direkt aufeinanderfolgende Datensätze fester Größe: <code>Data set 0</code>, <code>Data set 1</code>, <code>Data set 2</code> und <code>Data set 3</code>.\n</li><li>Ein Beschriftungstextkopf mit der Konfigurationsvorgabe: <code>NVM_DATASET_SELECTION_BITS configured to be four (bits), leaving twelve bit for the block number. Each NVRAM block thus can be subdivided in up to 16 datasets.</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Adressberechnung: Die <code>Address conversion</code> bestimmt anhand der 12 Bits der <code>Block number</code> die Basis-Startadresse des NVRAM-Blocks im linearen Speicher (gekennzeichnet durch den durchgezogenen Pfeil auf den Anfang von <code>Data set 0</code>).\n</li><li>Indizierter Zugriff („indexed“ addressing): Anhand des 4-Bit <code>Dataset index</code> wird über eine Offset-Berechnung gezielt auf den gewünschten Datensatz verwiesen (gekennzeichnet durch die gestrichelte Pfeillinie von der <code>Dataset index</code>-Klammer auf den Beginn von <code>Data set 2</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Parameter <code>NVM_DATASET_SELECTION_BITS</code> legt die Bitbreite des Indexanteils im 16-Bit-Blockbezeichner fest (im gezeigten Beispiel 4 Bits für bis zu 16 Datensätze je Block, verbleibend 12 Bits für maximal 4094 bzw. 4096 NVRAM-Blöcke).\n</li><li>Datensätze eines Blocks sind im Adressraum direkt benachbart angeordnet, sodass die Zieladresse jedes Datensatzes deterministisch über <code>Startadresse + (Dataset-Index * Blockgröße)</code> berechnet werden kann.\n</li></ul>"}, {"id": "FIG-27afc5c4183e6c00", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Adressierungsdiagramm zur Bitaufteilung und linearen Speicherabbildung im Kontext der AUTOSAR Flash EEPROM Emulation (FEE). Das Diagramm illustriert das Zusammenspiel zwischen einer 16-Bit-Blockkennung (NVRAM-Blocknummer und Dataset-Index) und dem physischen Adressraum der Datensätze.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei Hauptstrukturen:</p>\n<ul class=\"fig-list\"><li>Ein 16-Bit-Register/Feld, aufgeteilt in:\n<ul class=\"fig-list\"><li>12 höherwertige Bits (blau hinterlegt): Kennzeichnung für die logische <code>Block number</code>.\n</li><li>4 niederwertige Bits (türkis hinterlegt): Kennzeichnung für den <code>Dataset index</code>.\n</li></ul>\n</li><li>Eine funktionale Verarbeitungseinheit <code>Address conversion</code>, visualisiert als kreisförmiger Knoten mit Verbindungslinie zur <code>Block number</code>.\n</li><li>Ein vertikaler linearer Adressraum (Speicherabbild), schraffiert mit reservierten/umgebenden Speicherbereichen und einem aktiv adressierten Blockbereich. Dieser enthält vier direkt aufeinanderfolgende Datensätze fester Größe: <code>Data set 0</code>, <code>Data set 1</code>, <code>Data set 2</code> und <code>Data set 3</code>.\n</li><li>Ein Beschriftungstextkopf mit der Konfigurationsvorgabe: <code>NVM_DATASET_SELECTION_BITS configured to be four (bits), leaving twelve bit for the block number. Each NVRAM block thus can be subdivided in up to 16 datasets.</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Adressberechnung: Die <code>Address conversion</code> bestimmt anhand der 12 Bits der <code>Block number</code> die Basis-Startadresse des NVRAM-Blocks im linearen Speicher (gekennzeichnet durch den durchgezogenen Pfeil auf den Anfang von <code>Data set 0</code>).\n</li><li>Indizierter Zugriff („indexed“ addressing): Anhand des 4-Bit <code>Dataset index</code> wird über eine Offset-Berechnung gezielt auf den gewünschten Datensatz verwiesen (gekennzeichnet durch die gestrichelte Pfeillinie von der <code>Dataset index</code>-Klammer auf den Beginn von <code>Data set 2</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Parameter <code>NVM_DATASET_SELECTION_BITS</code> legt die Bitbreite des Indexanteils im 16-Bit-Blockbezeichner fest (im gezeigten Beispiel 4 Bits für bis zu 16 Datensätze je Block, verbleibend 12 Bits für maximal 4094 bzw. 4096 NVRAM-Blöcke).\n</li><li>Datensätze eines Blocks sind im Adressraum direkt benachbart angeordnet, sodass die Zieladresse jedes Datensatzes deterministisch über <code>Startadresse + (Dataset-Index * Blockgröße)</code> berechnet werden kann.\n</li></ul>"}, {"id": "FIG-a931f0d49a9790a2", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Adressierungsdiagramm zur Bitaufteilung und linearen Speicherabbildung im Kontext der AUTOSAR Flash EEPROM Emulation (FEE). Das Diagramm illustriert das Zusammenspiel zwischen einer 16-Bit-Blockkennung (NVRAM-Blocknummer und Dataset-Index) und dem physischen Adressraum der Datensätze.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei Hauptstrukturen:</p>\n<ul class=\"fig-list\"><li>Ein 16-Bit-Register/Feld, aufgeteilt in:\n<ul class=\"fig-list\"><li>12 höherwertige Bits (blau hinterlegt): Kennzeichnung für die logische <code>Block number</code>.\n</li><li>4 niederwertige Bits (türkis hinterlegt): Kennzeichnung für den <code>Dataset index</code>.\n</li></ul>\n</li><li>Eine funktionale Verarbeitungseinheit <code>Address conversion</code>, visualisiert als kreisförmiger Knoten mit Verbindungslinie zur <code>Block number</code>.\n</li><li>Ein vertikaler linearer Adressraum (Speicherabbild), schraffiert mit reservierten/umgebenden Speicherbereichen und einem aktiv adressierten Blockbereich. Dieser enthält vier direkt aufeinanderfolgende Datensätze fester Größe: <code>Data set 0</code>, <code>Data set 1</code>, <code>Data set 2</code> und <code>Data set 3</code>.\n</li><li>Ein Beschriftungstextkopf mit der Konfigurationsvorgabe: <code>NVM_DATASET_SELECTION_BITS configured to be four (bits), leaving twelve bit for the block number. Each NVRAM block thus can be subdivided in up to 16 datasets.</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Adressberechnung: Die <code>Address conversion</code> bestimmt anhand der 12 Bits der <code>Block number</code> die Basis-Startadresse des NVRAM-Blocks im linearen Speicher (gekennzeichnet durch den durchgezogenen Pfeil auf den Anfang von <code>Data set 0</code>).\n</li><li>Indizierter Zugriff („indexed“ addressing): Anhand des 4-Bit <code>Dataset index</code> wird über eine Offset-Berechnung gezielt auf den gewünschten Datensatz verwiesen (gekennzeichnet durch die gestrichelte Pfeillinie von der <code>Dataset index</code>-Klammer auf den Beginn von <code>Data set 2</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Parameter <code>NVM_DATASET_SELECTION_BITS</code> legt die Bitbreite des Indexanteils im 16-Bit-Blockbezeichner fest (im gezeigten Beispiel 4 Bits für bis zu 16 Datensätze je Block, verbleibend 12 Bits für maximal 4094 bzw. 4096 NVRAM-Blöcke).\n</li><li>Datensätze eines Blocks sind im Adressraum direkt benachbart angeordnet, sodass die Zieladresse jedes Datensatzes deterministisch über <code>Startadresse + (Dataset-Index * Blockgröße)</code> berechnet werden kann.\n</li></ul>"}, {"id": "FIG-9487a28453dae593", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Adressierungsdiagramm zur Bitaufteilung und linearen Speicherabbildung im Kontext der AUTOSAR Flash EEPROM Emulation (FEE). Das Diagramm illustriert das Zusammenspiel zwischen einer 16-Bit-Blockkennung (NVRAM-Blocknummer und Dataset-Index) und dem physischen Adressraum der Datensätze.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in drei Hauptstrukturen:</p>\n<ul class=\"fig-list\"><li>Ein 16-Bit-Register/Feld, aufgeteilt in:\n<ul class=\"fig-list\"><li>12 höherwertige Bits (blau hinterlegt): Kennzeichnung für die logische <code>Block number</code>.\n</li><li>4 niederwertige Bits (türkis hinterlegt): Kennzeichnung für den <code>Dataset index</code>.\n</li></ul>\n</li><li>Eine funktionale Verarbeitungseinheit <code>Address conversion</code>, visualisiert als kreisförmiger Knoten mit Verbindungslinie zur <code>Block number</code>.\n</li><li>Ein vertikaler linearer Adressraum (Speicherabbild), schraffiert mit reservierten/umgebenden Speicherbereichen und einem aktiv adressierten Blockbereich. Dieser enthält vier direkt aufeinanderfolgende Datensätze fester Größe: <code>Data set 0</code>, <code>Data set 1</code>, <code>Data set 2</code> und <code>Data set 3</code>.\n</li><li>Ein Beschriftungstextkopf mit der Konfigurationsvorgabe: <code>NVM_DATASET_SELECTION_BITS configured to be four (bits), leaving twelve bit for the block number. Each NVRAM block thus can be subdivided in up to 16 datasets.</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Adressberechnung: Die <code>Address conversion</code> bestimmt anhand der 12 Bits der <code>Block number</code> die Basis-Startadresse des NVRAM-Blocks im linearen Speicher (gekennzeichnet durch den durchgezogenen Pfeil auf den Anfang von <code>Data set 0</code>).\n</li><li>Indizierter Zugriff („indexed“ addressing): Anhand des 4-Bit <code>Dataset index</code> wird über eine Offset-Berechnung gezielt auf den gewünschten Datensatz verwiesen (gekennzeichnet durch die gestrichelte Pfeillinie von der <code>Dataset index</code>-Klammer auf den Beginn von <code>Data set 2</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Parameter <code>NVM_DATASET_SELECTION_BITS</code> legt die Bitbreite des Indexanteils im 16-Bit-Blockbezeichner fest (im gezeigten Beispiel 4 Bits für bis zu 16 Datensätze je Block, verbleibend 12 Bits für maximal 4094 bzw. 4096 NVRAM-Blöcke).\n</li><li>Datensätze eines Blocks sind im Adressraum direkt benachbart angeordnet, sodass die Zieladresse jedes Datensatzes deterministisch über <code>Startadresse + (Dataset-Index * Blockgröße)</code> berechnet werden kann.\n</li></ul>"}], "trans": [{"from": "FIG-b6f3161b044f63d6", "to": "FIG-27afc5c4183e6c00", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-27afc5c4183e6c00", "to": "FIG-a931f0d49a9790a2", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a931f0d49a9790a2", "to": "FIG-9487a28453dae593", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Gesamtdiagramm: Weißer oberer Rand und vertikale Abmessung des Diagrammbereichs vergrößert (Neurenderung/Layoutanpassung ohne inhaltliche Modifikation von Elementen oder Texten).\n</li></ul>"}]};
